2101	// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
2102	// The trailer is placed above the git comment block but below the user's message area,
2103	// with a comment explaining that the user can remove it if they don't want to link the commit
2104	// to the agent session. If prompt is non-empty, it's shown as context.
2105	func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt string) string {
2106		trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
2107		commentLines := []string{
2108			"# Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
2109		}
2110		if prompt != "" {
2111			commentLines = append(commentLines, "# Last Prompt: "+prompt)
2112		}
2113		commentLines = append(commentLines, "# The trailer will be added to your next commit based on this branch.")
2114		comment := strings.Join(commentLines, "\n")
2115	
2116		lines := strings.Split(message, "\n")
2117	
2118		// Find where the git comment block starts (first # line)
2119		commentStart := -1
2120		for i, line := range lines {
2121			if strings.HasPrefix(line, "#") {
2122				commentStart = i
2123				break
2124			}
2125		}
2126	
2127		if commentStart == -1 {
2128			// No git comments, append trailer at the end
2129			return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
2130		}
2131	
2132		// Split into user content and git comments
2133		userContent := strings.Join(lines[:commentStart], "\n")
2134		gitComments := strings.Join(lines[commentStart:], "\n")
